mapper.select:
SELECT bks.book_id as bookId, bks.book_title as bookTitle, bks.book_price as bookPrice, crt.book_count as bookCount, bks.book_flag as bookFlag FROM cart as crt
INNER JOIN books as bks ON crt.book_id = bks.book_id
WHERE crt.user_id = #{userID}

mapper.update:

UPDATE books
SET book_stock = book_stock - #{bookCount}
WHERE book_id = #{bookID}
  AND book_stock >= #{bookCount}
